function showView(view){state.view=view;saveURL();pause();$$('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#atlasView').hidden=view!=='atlas';$('#timeline').hidden=view!=='atlas';$('#contentView').hidden=view==='atlas';if(view==='atlas'){requestAnimationFrame(()=>{atlas?.map.resize();compareMap?.map.resize();});return;}if(view==='stories')renderStories();if(view==='library')renderLibrary();if(view==='sources')renderSources();}
const STORIES=[
 {id:'cities',title:{zh:'从聚落到国家',en:'From settlements to states'},description:{zh:'农业、城市、文字与政治组织如何在不同地区形成。',en:'Agriculture, cities, writing and political organization across regions.'},filter:e=>e.start<=-500&&['culture','politics','science','society'].includes(e.category)},
 {id:'east',title:{zh:'东亚的国家与思想',en:'States and ideas in East Asia'},description:{zh:'从早期国家到近代变革，把王朝史放进思想与技术的背景。',en:'Early states and modern transformations, alongside ideas and technologies.'},filter:e=>e.region==='east-asia'},
 {id:'south',title:{zh:'南亚与印度洋',en:'South Asia & the Indian Ocean'},description:{zh:'宗教、帝国、商业与反殖民运动交织的历史。',en:'Interwoven histories of religions, empires, commerce and anticolonial movements.'},filter:e=>['south-asia','southeast-asia'].includes(e.region)},
 {id:'africa',title:{zh:'非洲的多重世界',en:'The many worlds of Africa'},description:{zh:'尼罗河、萨赫勒、斯瓦希里海岸与独立运动。',en:'The Nile, the Sahel, the Swahili coast and independence movements.'},filter:e=>e.region==='africa'},
 {id:'americas',title:{zh:'美洲：接触之前与之后',en:'The Americas, before and after contact'},description:{zh:'原住民文明、殖民冲击、独立与社会权利。',en:'Indigenous civilizations, colonial disruption, independence and social rights.'},filter:e=>e.region==='americas'},
 {id:'oceania',title:{zh:'航向太平洋',en:'Across the Pacific'},description:{zh:'农业、远洋迁徙、殖民接触与政治变革。',en:'Agriculture, oceanic migrations, colonial encounters and political change.'},filter:e=>e.region==='oceania'},
 {id:'exchange',title:{zh:'连接世界的交换',en:'Exchanges that connected the world'},description:{zh:'陆海贸易、跨洋航行和全球市场形成。地图点代表相关地点，不描绘未经核验的路线。',en:'Overland and maritime trade, oceanic voyages and global markets. Markers are places, not reconstructed routes.'},filter:e=>e.category==='trade'},
 {id:'science',title:{zh:'知识如何改变世界',en:'Knowledge reshapes the world'},description:{zh:'从书写与印刷到工业、医学、太空和信息技术。',en:'From writing and printing to industry, medicine, space and information technology.'},filter:e=>e.category==='science'},
 {id:'thought',title:{zh:'信仰与思想的传播',en:'Religions and ideas in motion'},description:{zh:'宗教传统、思想运动与传播节点；不把文明简化为单一信仰。',en:'Religious traditions, intellectual movements and transmission, without reducing civilizations to one belief.'},filter:e=>e.category==='religion'},
 {id:'rights',title:{zh:'权利、革命与独立',en:'Rights, revolutions and independence'},description:{zh:'废奴、宪政、反殖民运动与公民权利。',en:'Abolition, constitutional government, anticolonial movements and civil rights.'},filter:e=>e.category==='society'||e.category==='politics'&&e.start>=1770},
 {id:'war',title:{zh:'战争与国际秩序',en:'War and international order'},description:{zh:'重要冲突及其政治后果。战役地点不等于整个战争范围。',en:'Major conflicts and political consequences. A battle marker does not show an entire war.'},filter:e=>e.category==='war'},
 {id:'planet',title:{zh:'人类与环境',en:'People and the environment'},description:{zh:'疾病、灾害、环境保护与全球合作。',en:'Disease, disasters, environmental protection and global cooperation.'},filter:e=>e.category==='disaster'||/climate|environment|smallpox|气候|天花/i.test(e.title.en+' '+e.title.zh)}
];
function storyEvents(story){const matches=events.filter(story.filter).sort((a,b)=>a.start-b.start);if(matches.length<=18)return matches;const ids=[...new Set(Array.from({length:18},(_,i)=>Math.round(i*(matches.length-1)/17)))];return ids.map(i=>matches[i]);}
function renderStories(){$('#contentView').innerHTML=`<span class="eyebrow">GUIDED JOURNEYS</span><h1>${text('沿着一条线索，穿过世界史','Follow a thread through world history')}</h1><p class="lead">${text('12条精选阅读路线，每一站都连接地图、事件背景与来源。路线是阅读顺序，不代表实际旅行或事件之间唯一的因果链。','Twelve thematic reading journeys connect maps, context and sources. Their order is a reading sequence, not a physical itinerary or a claim of unique causation.')}</p><div class="story-grid">${STORIES.map((s,i)=>`<button class="story-card" data-story="${s.id}"><span class="story-no">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">JOURNEY ${String(i+1).padStart(2,'0')}</span><h2>${bilingual(s.title)}</h2><p>${escape(text(s.description.zh,s.description.en))}</p><div class="foot">${storyEvents(s).length} ${text('个阅读节点 · 开始探索','stops · Explore')}</div></button>`).join('')}</div>`;$$('[data-story]').forEach(b=>b.onclick=()=>{state.story=STORIES.find(s=>s.id===b.dataset.story);state.storyIndex=0;const route=storyEvents(state.story);if(route.length)openEvent(route[0],{story:true});});}
function stepStory(delta){const route=storyEvents(state.story);state.storyIndex=Math.max(0,Math.min(route.length-1,state.storyIndex+delta));openEvent(route[state.storyIndex],{story:true});}
function renderLibrary(){const list=events.filter(e=>!libSearch||searchText(e).includes(libSearch.toLowerCase())).sort((a,b)=>a.start-b.start);$('#contentView').innerHTML=`<span class="eyebrow">WORLD CHRONICLE</span><h1>${text('世界历史年表','A chronicle of world history')}</h1><p class="lead">${text('按年代连续阅读所有已收录事件。每条包含中英文说明、时间精度、代表地点与来源；这是一份持续可扩充的精选年表。','Read all catalogued events chronologically. Each has bilingual context, date precision, a geographic anchor and sources. This is a curated, extensible chronicle.')}</p><div class="library-controls"><input id="libSearch" type="search" aria-label="${text('检索年表','Search chronicle')}" placeholder="${text('检索全部事件…','Search every event…')}" value="${escape(libSearch)}"><button id="exportEvents">${text('导出完整事件数据','Export all events')}</button><span class="tag">${list.length} ${text('条事件','events')}</span></div><div class="table-scroll"><table><thead><tr><th>${text('年代','Date')}</th><th>${text('事件','Event')}</th><th>${text('地区 / 主题','Region / theme')}</th><th>${text('来源','Sources')}</th></tr></thead><tbody>${list.map(e=>`<tr><td class="library-year">${escape(eventDate(e))}</td><td><button data-library="${e.id}" style="text-align:left;border:0;padding:0;color:var(--ink)">${bilingual(e.title)}</button></td><td>${text(...REGIONS[e.region])}<small class="secondary">${text(...CATS[e.category])}</small></td><td><a href="${escape(e.sources[0].url)}" target="_blank" rel="noopener">${text('查阅','Read')} (${e.sources.length})</a></td></tr>`).join('')}</tbody></table></div>`;$('#libSearch').onchange=e=>{libSearch=e.target.value;renderLibrary();$('#libSearch').focus();};$('#exportEvents').onclick=()=>downloadJSON(events,'meridian-events.json');$$('[data-library]').forEach(b=>b.onclick=()=>openEvent(events.find(e=>e.id===b.dataset.library)));}
function renderSources(){const m=catalog.metadata;const n=catalog.records.filter(r=>r.type==='POLITY');const translated=catalog.records.filter(r=>r.zhName).length;const counts=Object.keys(REGIONS).filter(k=>k!=='all').map(k=>[k,events.filter(e=>e.region===k).length]);const min=Math.min(...events.map(e=>e.start)),max=Math.max(...events.map(e=>e.end));$('#contentView').innerHTML=`<span class="eyebrow">EVIDENCE & COVERAGE</span><h1>${text('先看证据，再看地图','Evidence before certainty')}</h1><p class="lead">${text('地图是对历史证据的表达，而不是历史本身。本项目保留来源、原始名称、年代区间和不确定性，拒绝把数据空白填成确定事实。','A map expresses historical evidence; it is not history itself. This project preserves sources, original names, date intervals and uncertainty instead of inventing certainty in data gaps.')}</p><div class="stat-grid"><div class="stat-card"><strong>${m.counts.uniqueNames.toLocaleString()}</strong><span>${text('源数据独立名称（含关系）','Distinct source names (including relations)')}</span></div><div class="stat-card"><strong>${n.length.toLocaleString()}</strong><span>${text('政治疆域时间记录','Territory time records')}</span></div><div class="stat-card"><strong>${events.length}</strong><span>${text('双语历史事件','Bilingual historical events')}</span></div><div class="stat-card"><strong>12</strong><span>${text('专题阅读路线','Thematic journeys')}</span></div></div><div class="sources-actions"><button id="downloadEvents">${text('导出事件 JSON','Export events JSON')}</button><button id="downloadCatalog">${text('导出完整疆域目录','Export full territory catalog')}</button><button id="downloadCoverage">${text('导出覆盖报告','Export coverage report')}</button></div><section class="method-section"><h2>${text('数据覆盖与缺口','Coverage and gaps')}</h2><p>${text(`疆域覆盖公元前3400年至2024年；事件收录${yr(min)}至${yr(max)}。事件是精选集，并不宣称穷尽世界史。政治边界记录的时间、地区与尺度并不均匀，古代地区尤其稀疏。`,`Borders span 3400 BCE–2024 CE; events span ${formatYear(min,'en')}–${formatYear(max,'en')}. Events are a curated selection, not an exhaustive account of world history. Territory records have uneven temporal, regional and spatial coverage, especially in antiquity.`)}</p><p>${text('空白仅表示本数据集没有该位置在该年的疆域记录，不等于无人居住、没有文明或没有政治组织。海岸线使用 Natural Earth 现代概貌，未重建古代海平面。','Blank areas mean this dataset lacks a territory record at that place and year, not that there were no people, civilizations or political communities. Coastlines use the modern Natural Earth overview and do not reconstruct historical sea levels.')}</p><table><thead><tr><th>${text('地区','Region')}</th><th>${text('已收录事件数','Catalogued events')}</th></tr></thead><tbody>${counts.map(([k,n])=>`<tr><td>${text(...REGIONS[k])}</td><td>${n}</td></tr>`).join('')}</tbody></table></section><section class="method-section"><h2>${text('怎样理解“精度”','What precision means here')}</h2><ul><li>${text('年份可逐年选择，但同一条疆域记录可能跨越多年；区间内不做虚构插值。前1年直接跳到公元1年，没有公元0年。','Years are selectable individually, but one territory record can span many years; no artificial interpolation is used. 1 BCE is followed by 1 CE, without year zero.')}</li><li>${text('事件分别标为年份节点、约略年代或历史过程。地图上的一点可能是相关遗址，也可能只是一个代表地点；殖民扩张、宗教传播与战争不会被误称为一个地点。','Events are tagged as year-level dates, approximate dates or historical processes. A marker may identify a site or a representative location; colonial expansion, religious transmission and wars are not reduced to a single place.')}</li><li>${text('疆域采用原数据有效区间（起止年均包含）。上游6条记录的终点为0，原值保留并在记录中提示；不据此建立可选择的0年。','Source validity intervals include both endpoints. Six source records end at year 0; those raw values are retained and flagged, but year zero is not selectable.')}</li><li>${text('几何按0.02°作拓扑保留简化，保留小岛；这是概览显示，不支持精密边界测量。上游13条无效几何已记录，未擅自修补。','Geometry uses topology-preserving simplification at 0.02°, retaining small islands. This is overview mapping, not precise boundary measurement. Thirteen invalid source geometries are logged without silent repair.')}</li><li>${text('默认显示POLITY政体记录。RELATION联盟或共主关系往往与成员重叠，因此保留在目录中而不叠涂成另一国家。','The map displays POLITY records. RELATION records, such as unions, often overlap members; they are preserved in the catalog rather than painted as separate states.')}</li></ul></section><section class="method-section"><h2>${text('双语名称与编写边界','Bilingual labels and editorial limits')}</h2><p>${text(`中英文界面和${events.length}条事件内容已配对。疆域名称优先采用已校对中文名或与原始名称核对的Wikidata标签，原始英文名称始终保留。当前${translated.toLocaleString()}条源记录有中文补充名；缺少可靠译名时保留原文，不制造译名。`,`The interface and ${events.length} events have paired Chinese and English text. Territory labels prioritize reviewed Chinese names or Wikidata labels checked against source names; original English names are retained. ${translated.toLocaleString()} source records currently have supplementary Chinese labels. Missing labels remain in the original language rather than being invented.`)}</p><p>${text('事件文字是本项目的来源导向编辑摘要，并非逐条经过历史学家独立审稿；部分参考网页存在访问限制，未完成逐条全文核验。来源链接帮助追溯依据；不同研究的年代或解释可能不同，应在深入研究时交叉核对。','Event text consists of source-guided editorial summaries, not individually peer-reviewed scholarship; access restrictions prevented full-text verification of every referenced page. Source links enable follow-up; dates and interpretations can differ among studies and require cross-checking for research.')}</p></section><section class="method-section"><h2>${text('来源、版本与许可','Sources, versions and licensing')}</h2><table><thead><tr><th>${text('内容','Content')}</th><th>${text('来源及许可','Source and license')}</th></tr></thead><tbody><tr><td>${text('历史疆域与有效年代','Territories and validity intervals')}</td><td><a href="${m.repository}" target="_blank" rel="noopener">Cliopatria · Seshat Global History Databank</a>CC BY 4.0 · ${text('显示几何已简化','Display geometry simplified')}<br><code>${m.commit}</code></td></tr><tr><td>${text('地理底图','Geographic basemap')}</td><td><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth · Public domain</a></td></tr><tr><td>${text('补充中英文政体标签','Supplementary polity labels')}</td><td><a href="https://www.wikidata.org/wiki/Wikidata:Licensing" target="_blank" rel="noopener">Wikidata · CC0</a>${text('名称匹配校对见目录字段','See catalog fields for name matching checks')}</td></tr><tr><td>${text('事件内容','Event content')}</td><td>${text('逐条列出来源；本项目原创双语摘要 CC BY 4.0','Per-event sources; original bilingual summaries in this project: CC BY 4.0')}</td></tr><tr><td>${text('地图引擎','Map engine')}</td><td><a href="https://github.com/maplibre/maplibre-gl-js" target="_blank" rel="noopener">MapLibre GL JS · BSD-3-Clause</a></td></tr></tbody></table><p><a href="${m.sourceDownloadUrl}" target="_blank" rel="noopener">${text('下载固定版本原始疆域数据','Download the pinned original territory dataset')}</a><br><small>SHA-256: <code>${m.sourceZipSha256}</code></small></p></section><section class="method-section"><h2>${text('继续查阅其他历史图集','Explore complementary atlases')}</h2><p>${text('本项目借鉴交互方式，使用许可明确的开放数据；没有复制商业图集的专有数据库。下列项目可帮助比较不同重建与叙述。','This project combines interaction ideas with licensed open data; it does not copy proprietary atlas databases. These projects help compare reconstructions and narratives.')}</p>${sourceLinks([{title:'Phersu Atlas · '+text('详细历史地理','Detailed historical geography'),url:'https://www.phersu-atlas.com/'},{title:'Running Reality · '+text('时空地图与战役','Spatiotemporal maps and battles'),url:'https://www.runningreality.org/'},{title:'OpenHistoricalMap · '+text('社区历史地理','Community historical geography'),url:'https://www.openhistoricalmap.org/'},{title:'Chronosphere · '+text('地球与时间轴','Globe and timeline'),url:'https://worldbyyear.com/'},{title:'HistoryMaps · '+text('事件与故事','Events and stories'),url:'https://history-maps.com/timeline'}])}</section>`;$('#downloadEvents').onclick=()=>downloadJSON(events,'meridian-events.json');$('#downloadCatalog').onclick=()=>downloadJSON(catalog,'meridian-territory-catalog.json');$('#downloadCoverage').onclick=()=>downloadJSON({boundaryMetadata:m,eventCounts:Object.fromEntries(counts),events:events.length,coverage},'meridian-coverage.json');}
function noteTranslation(note){if(state.lang!=='en')return typeof note==='string'?note:note.zh;const notes={'中文名为与源Wikipedia词条对应的Wikidata标签；原始名称保留。':'Chinese labels come from Wikidata items associated with source Wikipedia articles. Original names are retained.','按源数据完整名称人工译名，保留国家、王朝及阶段区分。':'Editorial translations of exact source names retain distinctions between states, dynasties and periods.','暂无通过身份核对的中文标签，显示源数据原名。':'No identity-checked Chinese label is available; the original source name is shown.','关系名称保留原文，避免以参与者或统治者名称代替关系。':'The relation name is retained rather than replaced with a participant or ruler label.','源名称和百科关联存在年代歧义，保留原名，暂不译为后周。':'The source name and encyclopedia association have a chronological ambiguity. The original name is retained.'};return notes[note]||'Editorial label note: original source names are preserved.';}
function warningTranslation(w){if(state.lang!=='en')return w;const q=w.match(/Q\d+/g);if(q?.length===2)return `The source Wikidata ID ${q[0]} differs from ${q[1]}, the item associated with the source Wikipedia article. Labels from the mismatched ID were not used.`;if(w.includes('Later Zhou'))return 'The source applies Later Zhou to BCE intervals but links to the dynasty of 951–960 CE. Identity remains ambiguous; source geometry and dates are preserved.';if(w.includes('几何'))return 'The source polygon has geometry-validity issues. It has not been silently repaired and is used only for overview display.';if(w.includes('0年'))return 'The source interval has a year-zero endpoint. It is preserved in the raw data while the selectable timeline skips year zero.';if(w.includes('关系'))return 'This relation may overlap member polities; its encyclopedia ID may describe a participant or ruler.';if(w.includes('历史主题'))return 'The encyclopedia item describes a historical topic or list and was not used as a polity translation.';return 'The source encyclopedia association could not be verified; its automatic label was not adopted.';}
function renderHelp(){$('#helpContent').innerHTML=`<span class="eyebrow">READING THE ATLAS</span><h2>${text('使用经纬纪','Using Meridian Atlas')}</h2><ol><li>${text('拖动底部时间轴，或直接输入年份。负数代表公元前；时间轴分段缩放，为近现代保留更多空间。','Drag the timeline or enter a year. Negative numbers mean BCE. The timeline uses piecewise scaling to leave more room for recent centuries.')}</li><li>${text('点击政体查阅边界记录，点击事件查阅背景、意义和来源。搜索框同时检索事件与政体。','Click a polity for its boundary record, or an event for context, significance and sources. Search includes events and polities.')}</li><li>${text('选择地区、主题与时间窗口。全部年代会在地图上显示跨时期事件，疆域仍对应当前年。','Choose region, theme and time window. All periods shows events across time while borders remain at the selected year.')}</li><li>${text('年份对照展示两张同步视角的地图。播放按设定步长推进；两侧跳转按钮寻找数据中实际记录的下一次变化。','Compare years displays two maps with synchronized cameras. Playback follows the chosen step; the side buttons jump between recorded boundary changes.')}</li><li>${text('空白不是无人区，代表点不是影响范围，时间轴精度不是史料精度。请在“资料”中查看完整覆盖说明。','Blank is not uninhabited, a representative point is not an extent, and timeline precision is not evidence precision. Read Sources for coverage details.')}</li></ol><p>${text('键盘：空格播放/暂停；左右方向键移动所选步长；Esc关闭详情。','Keyboard: Space to play/pause; left/right arrows to move by the selected step; Esc closes details.')}</p>`;}
async function setCompareYear(value){state.compareYear=Math.max(-3400,Math.min(2024,normalizeYear(value)));$('#compareYear').value=state.compareYear;await compareMap.setYear(catalog,state.compareYear,state.lang);renderEvents();saveURL();}
async function toggleCompare(){state.compare=!state.compare;$('#compareBtn').classList.toggle('active',state.compare);$('.map-stage').classList.toggle('comparing',state.compare);$('#map2').hidden=!state.compare;$('#compareHeading').hidden=!state.compare;$('#compareYear').value=state.compareYear;if(state.compare){compareMap=new AtlasMap('map2',{onPolity:r=>openPolity(r,compareMap)});await compareMap.ready;compareMap.showEvents=state.events;compareMap.showLabels=state.labels;compareMap.toggleBorders(state.borders);compareMap.map.jumpTo({center:atlas.map.getCenter(),zoom:atlas.map.getZoom(),bearing:atlas.map.getBearing(),pitch:atlas.map.getPitch()});compareMap.projection(state.projection==='globe');await compareMap.setYear(catalog,state.compareYear,state.lang);let syncing=false;const sync=(a,b)=>{if(syncing||!state.compare)return;syncing=true;b.jumpTo({center:a.getCenter(),zoom:a.getZoom(),bearing:a.getBearing(),pitch:a.getPitch()});syncing=false;};const left=()=>compareMap&&sync(atlas.map,compareMap.map),right=()=>compareMap&&sync(compareMap.map,atlas.map);atlas.map.on('move',left);compareMap.map.on('move',right);compareMap.cleanup=()=>atlas.map.off('move',left);}else{compareMap?.cleanup?.();compareMap?.destroy();compareMap=null;if(state.selectedSide==='right'){$('#detailPanel').hidden=true;state.selected=null;state.selectedPolity=null;state.selectedSide='left';}}atlas.map.resize();compareMap?.map.resize();renderEvents();saveURL();}
function downloadJSON(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function copyView(){saveURL();try{await navigator.clipboard.writeText(location.href);notify(text('视图链接已复制','View link copied'));}catch{notify(text('请复制浏览器地址栏中的链接','Copy the link in the address bar'));}}
function bind(){for(const id of ['yearInput','compareYear'])$('#'+id).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();e.target.blur();if(id==='yearInput')setYear(e.target.value);else if(compareMap)setCompareYear(e.target.value);}};$('#yearInput').onchange=e=>{pause();setYear(e.target.value);};let debounce;$('#yearSlider').oninput=e=>{pause();const y=unscaled(+e.target.value);$('#bigYear').textContent=yr(y);$('#yearInput').value=y;clearTimeout(debounce);debounce=setTimeout(()=>setYear(y),180);};$('#yearSlider').onchange=e=>{clearTimeout(debounce);setYear(unscaled(+e.target.value));};$('#language').onchange=e=>{state.lang=e.target.value;renderLanguage();setYear(state.year);if(state.selected)renderEventDetail(state.selected);if(state.selectedPolity)openPolity(state.selectedPolity,state.selectedSide==='right'&&compareMap?compareMap:atlas);if(state.view!=='atlas')showView(state.view);};$('#search').oninput=e=>{state.search=e.target.value;renderEvents();saveURL();};for(const [id,key]of [['region','region'],['category','category']])$('#'+id).onchange=e=>{state[key]=e.target.value;renderEvents();saveURL();};$('#window').onchange=e=>{state.span=+e.target.value;renderEvents();saveURL();};$('#nearBtn').onclick=()=>{state.allTime=false;renderYear();renderEvents();};$('#allBtn').onclick=()=>{state.allTime=true;renderYear();renderEvents();};$('#playBtn').onclick=()=>{if(playing)pause();else{playing=true;$('#playBtn').textContent='Ⅱ';$('#playBtn').setAttribute('aria-label',text('暂停','Pause'));playTick();}};
 const changes=[...new Set(catalog.records.filter(r=>r.type==='POLITY').flatMap(r=>[r.start,r.end===-1?1:r.end+1]))].filter(y=>y&&y>=-3400&&y<=2024).sort((a,b)=>a-b);$('#prevChange').onclick=()=>{pause();setYear([...changes].reverse().find(y=>y<state.year)??state.year);};$('#nextChange').onclick=()=>{pause();setYear(changes.find(y=>y>state.year)??state.year);};$('#projectionBtn').onclick=()=>{state.projection=state.projection==='mercator'?'globe':'mercator';atlas.projection(state.projection==='globe');compareMap?.projection(state.projection==='globe');$('#projectionBtn').textContent=state.projection==='mercator'?text('◉ 地球','◉ Globe'):text('▧ 平面','▧ Flat');saveURL();};$('#bordersBtn').onclick=()=>{state.borders=!state.borders;$('#bordersBtn').classList.toggle('active',state.borders);atlas.toggleBorders(state.borders);compareMap?.toggleBorders(state.borders);};$('#eventsBtn').onclick=()=>{state.events=!state.events;$('#eventsBtn').classList.toggle('active',state.events);atlas.showEvents=state.events;if(compareMap)compareMap.showEvents=state.events;renderEvents();};$('#labelsBtn').onclick=()=>{state.labels=!state.labels;$('#labelsBtn').classList.toggle('active',state.labels);atlas.showLabels=state.labels;atlas.refreshLabels();if(compareMap){compareMap.showLabels=state.labels;compareMap.refreshLabels();}};$('#resetBtn').onclick=()=>atlas.reset();$('#compareBtn').onclick=toggleCompare;$('#closeCompare').onclick=toggleCompare;$('#compareYear').onchange=e=>setCompareYear(e.target.value);$('#copyBtn').onclick=copyView;$$('#tabs button').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('.dialog-close').onclick=()=>$('#helpDialog').close();document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||$('#helpDialog').open)return;if(e.code==='Space'&&state.view==='atlas'){e.preventDefault();$('#playBtn').click();}if(e.code==='ArrowRight'&&state.view==='atlas'){e.preventDefault();pause();setYear(stepYear(state.year,+$('#step').value));}if(e.code==='ArrowLeft'&&state.view==='atlas'){e.preventDefault();pause();setYear(stepYear(state.year,-$('#step').value));}if(e.key==='Escape'){$('#detailPanel').hidden=true;state.story=null;}});}
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;const tools=[{name:'atlas_get_state',description:'Read the current historical year, filters, selected event and dataset coverage.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({year:state.year,language:state.lang,region:state.region,category:state.category,event:state.selected?.id??null,eventCount:events.length,boundaryRange:[-3400,2024]})},{name:'atlas_navigate_year',description:'Navigate the visible atlas to a historical year; negative numbers mean BCE and year zero is invalid.',inputSchema:{type:'object',properties:{year:{type:'integer',minimum:-70000,maximum:2026}},required:['year'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!Number.isInteger(input?.year)||!input.year||input.year< -70000||input.year>2026)throw Error('Expected an integer from -70000 to 2026, excluding 0');showView('atlas');await setYear(input.year);return {year:state.year,polities:atlas.active?.length||0};}},{name:'atlas_search_events',description:'Read source-linked bilingual events matching text without changing the page.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(typeof input?.query!=='string')throw Error('query must be text');return events.filter(e=>searchText(e).includes(input.query.toLowerCase())).slice(0,20).map(e=>({id:e.id,title:e.title,start:e.start,end:e.end,sources:e.sources}));}}];tools.forEach(t=>Promise.resolve(c.registerTool(t)).catch(()=>{}));}
async function init(){try{[catalog,events]=await Promise.all([readJSON('data/catalog.json.gz'),readJSON('data/events.json')]);coverage=await readJSON('data/coverage.json').catch(()=>[]);renderLanguage();atlas=new AtlasMap('map',{onPolity:openPolity});bind();$('#search').value=state.search;await setYear(state.year);atlas.projection(state.projection==='globe');if(params.get('compare')==='1')await toggleCompare();registerTools();if(params.get('event')){const e=events.find(e=>e.id===params.get('event'));if(e)await openEvent(e,{whichMap:params.get('side')==='right'&&compareMap?compareMap:atlas});}if(params.get('view')&&['stories','library','sources'].includes(params.get('view')))showView(params.get('view'));}catch(e){$('#loading').hidden=false;$('#loading').textContent=text('数据未能载入。请通过项目启动器或在线地址打开。','Data could not load. Use the project launcher or hosted URL.');console.error(e);}}
init();
